import 'package:hive/hive.dart';

part 'transaction.g.dart';

/// A single financial transaction.
///
/// Extends [HiveObject] for local persistence.
/// The [TypeAdapter] is generated by `hive_generator` in `transaction.g.dart`.
///
/// Fields:
/// - [id]: unique identifier (timestamp in milliseconds)
/// - [amount]: amount in euros (always positive, the sign is given by [isIncome])
/// - [isIncome]: true = income, false = expense
/// - [date]: transaction date, used by the monthly filter
/// - [category]: transaction category (required, chosen from [CategoryProvider])
///
/// Note: [HiveField(1)] (formerly `title`) is no longer used but is kept
/// in the adapter for backward compatibility with existing Hive data.
@HiveType(typeId: 0)
class Transaction extends HiveObject {
  @HiveField(0)
  final String id;

  @HiveField(2)
  final double amount;

  @HiveField(3)
  final bool isIncome;

  @HiveField(4)
  final DateTime date;

  @HiveField(5)
  final String category;

  Transaction({
    required this.id,
    required this.amount,
    required this.isIncome,
    required this.date,
    required this.category,
  });
}
